import json, sys
from collections import Counter
data = json.load(sys.stdin)
result = json.loads(data['result'])
exps = result['data']['experiments']
# exps is a dict, keys are exp_ids
running = {k: v for k, v in exps.items() if v.get('status') == 'RUNNING'}
print('=== RUNNING ===')
for k, v in running.items():
    print(f'  {k}: gpu={v.get(\"gpu_ids\",\"?\")}, hyp={str(v.get(\"hypothesis\",\"\"))[:80]}')

for st in ['ANALYZING', 'PREPARING', 'QUEUED', 'ALLOCATED', 'PENDING']:
    subset = {k: v for k, v in exps.items() if v.get('status') == st}
    if subset:
        print(f'\n=== {st} ({len(subset)}) ===')
        for k, v in subset.items():
            print(f'  {k}: {v.get(\"conclusion\",\"\")}')

counts = Counter(v['status'] for v in exps.values())
print(f'\n=== STATUS COUNTS ===')
for k, v in sorted(counts.items()):
    print(f'  {k}: {v}')
"

